package tsgp.yah_enterprise.transfer.domain.valueobject;

import tsgp.yah_enterprise.transfer.domain.exception.InvalidTransferException;

/** The human number of a transfer, TRF-000001. Generated by the system from a sequence, never edited. */
public record TransferNumber(String value) {

    public TransferNumber {
        if (value == null || value.isBlank()) {
            throw new InvalidTransferException("Transfer number is required");
        }
    }

    public static TransferNumber of(String value) {
        return new TransferNumber(value);
    }

    public static TransferNumber fromSequence(long seq) {
        return new TransferNumber("TRF-" + String.format("%06d", seq));
    }

    @Override
    public String toString() {
        return value;
    }
}
